17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
107	        owner.setCity(resolveCity(owner.getCity()));
108	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
115	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
116	        this.clinicService.saveOwner(owner);
117	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
118	        headers.setLocation(UriComponentsBuilder.newInstance()
119	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
120	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
126	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
127	        if (currentOwner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        currentOwner.setAddress(ownerFieldsDto.getAddress());
131	        currentOwner.setCity(ownerFieldsDto.getCity());
132	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
133	        currentOwner.setLastName(ownerFieldsDto.getLastName());
134	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
135	        this.clinicService.saveOwner(currentOwner);
136	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Transactional
141	    @Override
142	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        this.clinicService.deleteOwner(owner);
148	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        HttpHeaders headers = new HttpHeaders();
159	        Pet pet = petMapper.toPet(petFieldsDto);
160	        owner.setId(ownerId);
161	        pet.setOwner(owner);
162	        pet.getType().setName(null);
163	        this.clinicService.savePet(pet);
164	        PetDto petDto = petMapper.toPetDto(pet);
165	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
166	            .buildAndExpand(pet.getId()).toUri());
167	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
173	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
174	        if (currentOwner != null) {
175	            Pet currentPet = this.clinicService.findPetById(petId);
176	            if (currentPet != null) {
177	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
178	                currentPet.setName(petFieldsDto.getName());
179	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
180	                this.clinicService.savePet(currentPet);
181	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
182	            }
183	        }
184	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
190	        HttpHeaders headers = new HttpHeaders();
191	        Visit visit = visitMapper.toVisit(visitFieldsDto);
192	        Pet pet = new Pet();
193	        pet.setId(petId);
194	        visit.setPet(pet);
195	        this.clinicService.saveVisit(visit);
196	        VisitDto visitDto = visitMapper.toVisitDto(visit);
197	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
198	            .buildAndExpand(visit.getId()).toUri());
199	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
200	    }
201	
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner != null) {
208	            Pet pet = owner.getPet(petId);
209	            if (pet != null) {
210	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
211	            }
212	        }
213	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	    }
215	
216	    /**
217	     * Resolves the city name to use for a newly created owner. The supplied city is
218	     * title-cased (each whitespace-separated word starts with an upper-case letter and the
219	     * remaining letters are lower-cased), for example {@code "new york"} becomes
220	     * {@code "New York"}. However, if an owner already exists in that city (matched ignoring
221	     * letter case), the existing owner's exact spelling of the city name is reused instead, so
222	     * that all owners in a city share a single canonical spelling.
223	     *
224	     * @param city the city supplied for the owner being created, may be {@code null}
225	     * @return the city name to store and return for the owner
226	     */
227	    private String resolveCity(String city) {
228	        if (city == null) {
229	            return null;
230	        }
231	        String existingCity = this.clinicService.findAllOwners().stream()
232	            .map(Owner::getCity)
233	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
234	            .findFirst()
235	            .orElse(null);
236	        if (existingCity != null) {
237	            return existingCity;
238	        }
239	        return toTitleCase(city);
240	    }
241	
242	    /**
243	     * Title-cases the given text so that each whitespace-separated word starts with an
244	     * upper-case letter and the remaining letters are lower-cased, for example
245	     * {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}. The original
246	     * spacing between words is preserved.
247	     *
248	     * @param value the text to title-case
249	     * @return the title-cased text
250	     */
251	    private static String toTitleCase(String value) {
252	        StringBuilder result = new StringBuilder(value.length());
253	        boolean startOfWord = true;
254	        for (int i = 0; i < value.length(); i++) {
255	            char ch = value.charAt(i);
256	            if (Character.isWhitespace(ch)) {
257	                startOfWord = true;
258	                result.append(ch);
259	            } else if (startOfWord) {
260	                result.append(Character.toUpperCase(ch));
261	                startOfWord = false;
262	            } else {
263	                result.append(Character.toLowerCase(ch));
264	            }
265	        }
266	        return result.toString();
267	    }
268	
269	    /**
270	     * Builds the customer code for a newly created owner, formatted as
271	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
272	     * owners already registered in that city, zero-padded to four digits (e.g.
273	     * {@code 'LONDON-0007'}). Cities are matched ignoring letter case so the sequence is
274	     * consistent with the upper-cased prefix.
275	     *
276	     * @param city the city of the owner being created
277	     * @return the assigned customer code
278	     */
279	    private String nextCustomerCode(String city) {
280	        long ownersInCity = this.clinicService.findAllOwners().stream()
281	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
282	            .count();
283	        return city.toUpperCase() + "-" + String.format("%04d", ownersInCity + 1);
284	    }
285	
286	    /**
287	     * Determines whether an owner already exists that uses the same telephone number as the
288	     * given candidate. Telephone numbers are compared digits-only, so formatting characters
289	     * such as spaces, dashes and parentheses are ignored.
290	     *
291	     * @param owner the candidate owner to check
292	     * @return {@code true} if an owner with the same telephone number already exists
293	     */
294	    private boolean isDuplicateOwner(Owner owner) {
295	        String telephone = normalizeTelephone(owner.getTelephone());
296	        return this.clinicService.findAllOwners().stream()
297	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
298	    }
299	
300	    /**
301	     * Determines whether an owner already exists that uses the same email address as the
302	     * given candidate. Owners without an email address are never considered duplicates.
303	     * The comparison ignores letter case and surrounding or repeated whitespace.
304	     *
